package com.tarapickle.identity.domain;
import com.tarapickle.identity.domain.model.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
class UserTest {private final Instant now=Instant.parse("2026-08-21T10:00:00Z"); @Test void verifiesPendingAccount(){User u=new User(UUID.randomUUID(),"player@example.com","Ada","Lovelace",now);u.verifyEmail(now.plusSeconds(1));assertThat(u.getStatus()).isEqualTo(AccountStatus.ACTIVE);assertThat(u.getEmailVerifiedAt()).isNotNull();} @Test void cannotVerifyTwice(){User u=new User(UUID.randomUUID(),"player@example.com","Ada","Lovelace",now);u.verifyEmail(now);assertThatThrownBy(()->u.verifyEmail(now)).isInstanceOf(IllegalStateException.class);} @Test void onlyActiveAccountCanBeSuspended(){User u=new User(UUID.randomUUID(),"player@example.com","Ada","Lovelace",now);assertThatThrownBy(()->u.suspend(now)).isInstanceOf(IllegalStateException.class);}}
